    <p class="hint"><?php echo htmlspecialchars(ny($x["when"]), ENT_QUOTES, 'UTF-8'); ?><?php if ($x["school"] !== '') { ?> · school: <?php echo htmlspecialchars($x["school"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if ($x["pickup"] !== '') { ?> · picks up: <?php echo htmlspecialchars($x["pickup"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if ($x["campType"] !== '') { ?> · <?php echo htmlspecialchars($x["campType"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if ($x["sentBy"] !== '') { ?> · sent by: <?php echo htmlspecialchars($x["sentBy"], ENT_QUOTES, 'UTF-8'); ?><?php } ?> · <code><?php echo htmlspecialchars($x["id"], ENT_QUOTES, 'UTF-8'); ?></code></p>
    <p><b><?php echo htmlspecialchars(state_line($x), ENT_QUOTES, 'UTF-8'); ?></b><?php if ((int) $x["row"]["decided"] > 0) { ?> · <?php echo htmlspecialchars(ny($x["row"]["decided"]), ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if ((int) $x["row"]["pr"] > 0 && $REPO !== '') { ?> · <a href="https://github.com/<?php echo htmlspecialchars($REPO, ENT_QUOTES, 'UTF-8'); ?>/pull/<?php echo (int) $x["row"]["pr"]; ?>" rel="noopener" target="_blank">pull request #<?php echo (int) $x["row"]["pr"]; ?></a><?php } ?><?php $tl = told_line($x["row"]); if ($tl !== '') { ?> · <?php echo htmlspecialchars($tl, ENT_QUOTES, 'UTF-8'); ?><?php } ?></p>
    <?php if ($x["website"] !== '') { ?><p>Website: <a href="<?php echo htmlspecialchars($x["website"], ENT_QUOTES, 'UTF-8'); ?>" rel="noopener nofollow" target="_blank"><?php echo htmlspecialchars($x["website"], ENT_QUOTES, 'UTF-8'); ?></a></p><?php } ?>
    <?php if ($x["details"] !== '') { ?><pre class="edit-ask"><?php echo htmlspecialchars($x["details"], ENT_QUOTES, 'UTF-8'); ?></pre><?php } ?>
    
  </div><?php } ?>
  </details><?php } ?>
  <p><a class="btn" href="../">Back to editing</a> <a class="btn" href="../claims/">Claims and proposed changes</a></p>
</div>
